/* ──────────────────────────────────────────────────────────────────────────
 * 5 · Canonical CTA tokens (PLAN-SCHEMA §14.6)
 *     Never write raw `/plan/...` hrefs into event_log.cta_href — store
 *     a `plan:<entity>:<id>[?key=value]` token and resolve client-side
 *     per the user's new_plan_experience flag state.
 * ────────────────────────────────────────────────────────────────────────── */

/** Plan CTA entity type — the second segment of the canonical token. */
export type PlanCtaEntity =
  | 'goal'
  | 'task'
  | 'objective'
  | 'rec'
  | 'report'
  | 'history'
  | 'team'
  | 'gutcheck'
  | 'pressure_test';

/**
 * Broad template literal type for any plan CTA token. Narrower helpers
 * below model the common cases.
 *
 * Format: `plan:<entity>:<id>[?key=value[&key=value]*]`
 * Examples:
 *   `plan:goal:abc-123`
 *   `plan:goal:abc-123?modal=pressure-test`
 *   `plan:goal:abc-123?gutcheck=jkl-012`
 *   `plan:task:def-456`
 *   `plan:rec:ghi-789`
 *   `plan:team:frac-999`
 *   `plan:history:xyz-000`
 *   `plan:report:rep-111`
 */
export type PlanCtaToken = `plan:${string}:${string}`;

/** Narrower entity-scoped tokens — useful for switch/case on event readers. */
export type PlanGoalCtaToken = `plan:goal:${string}`;
export type PlanTaskCtaToken = `plan:task:${string}`;
export type PlanObjectiveCtaToken = `plan:objective:${string}`;
export type PlanRecCtaToken = `plan:rec:${string}`;
export type PlanReportCtaToken = `plan:report:${string}`;
export type PlanHistoryCtaToken = `plan:history:${string}`;
export type PlanTeamCtaToken = `plan:team:${string}`;
export type PlanGutcheckCtaToken = `plan:goal:${string}?gutcheck=${string}`;
export type PlanPressureTestCtaToken = `plan:goal:${string}?modal=pressure-test`;

/** Parsed form of a CTA token — what the route resolver emits. */
export interface ParsedPlanCta {
  raw: PlanCtaToken;
  section: 'plan';
  entity: PlanCtaEntity;
  id: string;
  params: Record<string, string>;
}

/* ──────────────────────────────────────────────────────────────────────────
 * 6 · PlanAction — the permissions-matrix action union (§16.1)
 *     Mirrors plan_can()'s `p_action` parameter values exactly.
 * ────────────────────────────────────────────────────────────────────────── */

export type PlanAction =
  // Plan workspace
  | 'view_plan_workspace'
  // Strategic Goals
  | 'create_strategic_goal'
  | 'edit_strategic_goal'
  | 'pin_strategic_goal'
  | 'kill_strategic_goal'
  | 'pivot_strategic_goal'
  | 'set_goal_state_manual'
  | 'edit_disprove_assumption'
  // Objectives / Tasks
  | 'create_objective'
  | 'edit_objective'
  | 'create_task'
  | 'assign_task_self'
  | 'assign_task_others'
  | 'close_own_task'
  | 'delete_task'
  // Fractional team
  | 'invite_fractional'
  | 'end_engagement'
  | 'set_capacity_retainer'
  // Gutcheck / Pressure-test
  | 'decide_gutcheck'
  | 'start_pressure_test'
  | 'close_pressure_test'
  // Report
  | 'draft_report'
  | 'edit_report_draft'
  | 'send_report'
  | 'view_sent_reports'
  // History
  | 'view_history'
  | 'add_manual_history'
  | 'mark_history_outcome'
  // Settings
  | 'change_nudge_frequency'
  | 'change_specialist_behaviour'
  | 'manage_permissions';

/* ──────────────────────────────────────────────────────────────────────────
 * 7 · Discriminated union shortcuts — useful for server-action returns
 * ────────────────────────────────────────────────────────────────────────── */

export type PlanTable =
  | 'strategic_goals'
  | 'disprove_assumptions'
  | 'fractional_executives'
  | 'fractional_engagements'
  | 'goal_team_assignments'
  | 'history_entries'
  | 'pressure_test_sessions'
  | 'gutcheck_sessions'
